from mk import *
from lib import fbd
STRICT["on"] = True
import math
NE = 65 * 10 * math.cos(math.radians(53)); DE = 7 / math.sin(math.radians(53)); f = (100 * 10 * 11 - 100 * 10 * 7) / DE

def fig():
    g = Fig(560, 280, "מסלול החלקה מכוסה שלג: A בגובה 12 מטר, B בגובה 7 מטר בתחתית קשת ברדיוס 5 מטר, C בראש קשת ברדיוס 5 מטר, D בגובה 1 מטר בתחתית, קטע ישר DF בשיפוע 53 מעלות, E בגובה 8 מטר ו-F בגובה 14 מטר")
    g.ground(30, 530, 250)
    Y = lambda h: 250 - h * 15
    g.path(f"M 70,{Y(12)} Q 140,{Y(6.5)} 170,{Y(7)} Q 220,{Y(9.5)} 250,{Y(9.5)} Q 320,{Y(9)} 370,{Y(1)} Q 380,{Y(0.6)} 395,{Y(1.6)} L 470,{Y(14)}", width=2.5)
    g.block(78, Y(12) - 6, 22, 12, None, angle=-25)
    for x, h, t in ((70, 12, "A"), (170, 7, "B"), (250, 9.5, "C"), (380, 1, "D"), (440, 8, "E"), (470, 14, "F")):
        g.dot(x, Y(h)); g.text(x + 8, Y(h) - 8, t, anchor="start")
    for x, h, lab in ((60, 12, "12m"), (170, 7, "7m"), (440, 8, "8m"), (480, 14, "14m")):
        g.line(x, Y(h), x, 250, stroke="var(--d-dim)", width=1, dash="4 3"); g.text(x - 4, (Y(h) + 250) / 2, lab, cls="dim", anchor="end")
    g.circle(170, Y(7) - 75, 75, fill="none", stroke="var(--d-dim)", dash="4 4"); g.text(170, Y(7) - 80, "R = 5m", cls="dim")
    g.circle(250, Y(9.5) + 75, 75, fill="none", stroke="var(--d-dim)", dash="4 4"); g.text(250, Y(9.5) + 84, "R = 5m", cls="dim")
    g.angle(390, 250, 26, 0, 53, "53°", lr=40)
    return g

E(id="bagrut-2014-q4", year=2014, label="2014 שאלה 4", topic="energy", sub="en-conservation", diff=4, fig=fig,
  stem=r"מסלול החלקה בנוי מקטעים ישרים ומקשתות של מעגלים ברדיוס $5\,\text{m}$. המסלול מכוסה שלג, ולכן מזניחים את החיכוך. בנקודה $A$ על המסלול עומדת מזחלת שמסתה $35\,\text{kg}$. גיל, שמסתו $65\,\text{kg}$, מתיישב במזחלת כשהיא במנוחה.",
  parts=[
    P("א", r"משחררים את המזחלת ממנוחה, והיא נעה על המסלול בלי לעזוב אותו. מה גודל המהירות שלה בנקודה $B$?", num(10, "m/s"), ["principle"], [
        S(r"שימור אנרגיה", r"אין חיכוך, והכוח הנורמלי ניצב לתנועה. המזחלת יורדת משתים עשרה מטר לשבעה. המסה מצטמצמת", r"m \cdot 10 \cdot 12 = \tfrac{1}{2}m\,v_B^2 + m \cdot 10 \cdot 7 \;\Rightarrow\; v_B = \sqrt{100} = 10\,\text{m/s}", eq=r"E_k = \tfrac{1}{2}mv^2,\quad U_G = mgh"),
    ], r"$10\,\text{m/s}$", key=r"vB=10 m/s"),
    P("ב", r"האם התשובה לסעיף א הייתה משתנה, אם נער אחר, במסה אחרת, היה יושב במזחלת? נמקו.", choice(["כן", "לא"], 1), ["principle"], [
        S(r"המסה מצטמצמת", r"גם האנרגיה הקינטית וגם אנרגיית הגובה פרופורציוניות למסה, ולכן המהירות לא תלויה בה", r"\tfrac{1}{2}m v^2 = m g\,\Delta h \;\Rightarrow\; v = \sqrt{2g\,\Delta h}"),
    ], r"לא: המהירות לא תלויה במסה", key=r"לא"),
    P("ג", r"במזחלת יש מאזני קפיץ, והמשטח העליון שלהם תמיד מקביל למסלול. גיל יושב על המאזניים, והרגליים שלו באוויר. באיזה גובה מעל הקרקע צריכה להיות הנקודה $C$, כדי שגיל יהיה חסר משקל כשהוא עובר בה? פרטו את החישוב.", num(9.5, "m"), ["fbd", "principle"], [
        X(r"המאזניים מראים את הכוח הנורמלי שהם מפעילים על גיל. חסר משקל פירושו שהכוח הזה אפס. הכיוון החיובי הוא אל מרכז הקשת, כלפי מטה."),
        D(r"תרשים הכוחות על גיל בנקודה C", lambda: fbd([("m_G g", -90, 1.0)],
            "תרשים כוחות על גיל בראש הקשת, כשהוא חסר משקל: רק כוח הכובד, כלפי מטה, אל מרכז הקשת. הכיוון החיובי אל המרכז",
            positive=-90, body="ball")),
        S(r"משוואת כוחות בכיוון המרכז", r"הכוח הנורמלי אפס, ולכן הכובד לבדו נותן את התאוצה אל המרכז. המסה מצטמצמת", r"m_G g - 0 = m_G\,\frac{v_C^2}{R} \;\Rightarrow\; v_C^2 = 10 \cdot 5 = 50\,\text{m}^2/\text{s}^2", eq=r"\Sigma\vec F = m\vec a,\qquad a_R = \frac{v^2}{r}"),
        S(r"שימור אנרגיה מהנקודה A", r"המזחלת מתחילה ממנוחה בגובה שתים עשרה מטר", r"10 \cdot 12 = \tfrac{1}{2} \cdot 50 + 10\,h_C \;\Rightarrow\; h_C = 9.5\,\text{m}", eq=r"E_k = \tfrac{1}{2}mv^2,\quad U_G = mgh"),
    ], r"$9.5\,\text{m}$", key=r"hC=9.5 m"),
    P("ד", r"מה מראים המאזניים, בניוטון, כשהמזחלת עוברת בנקודה $E$?", num(NE, "N"), ["fbd", "principle"], [
        D(r"תרשים הכוחות על גיל בנקודה E", lambda: fbd([("m_G g", -90, 1.0), ("N", 143, 0.6)],
            "תרשים כוחות על גיל בקטע הישר: כוח הכובד כלפי מטה, והכוח הנורמלי של המאזניים ניצב למסלול",
            body="block", tilt=53, surface="below")),
        S(r"משוואת כוחות בניצב למסלול", r"הקטע ישר, ולכן אין תאוצה בניצב למסלול. הכיוון החיובי הוא כיוון הכוח הנורמלי", r"N - m_G g\cos 53^\circ = 0", eq=r"\Sigma\vec F = m\vec a"),
        S(r"מציבים", r"המסה של גיל לבד, כי המאזניים מראים את הכוח עליו", r"N = 65 \cdot 10 \cdot 0.602 \approx 391.2\,\text{N}"),
    ], r"$\approx 391.2\,\text{N}$", key=r"N=391.2 N"),
    P("ה", r"ביום חם השלג נמס בקטע $DF$, ונוצר בו חיכוך בין המסלול למזחלת. בגלל החיכוך המזחלת נעצרת לרגע בנקודה $E$. מה גודל כוח החיכוך שפעל על המזחלת בקטע $DE$?", num(f, "N"), ["principle"], [
        X(r"מחשבים את המזחלת וגיל יחד, מאה קילוגרם. כוח החיכוך קבוע לאורך הקטע הישר."),
        S(r"האנרגיה בנקודה D", r"שימור אנרגיה עד לנקודה הזו, כי עד שם אין חיכוך. בוחרים גובה אפס בנקודה הזו. המזחלת ירדה אחד עשר מטר", r"E_D = 100 \cdot 10 \cdot (12 - 1) = 11000\,\text{J}", eq=r"E_k = \tfrac{1}{2}mv^2,\quad U_G = mgh"),
        S(r"האנרגיה בנקודה E", r"המזחלת עומדת, ונמצאת שבעה מטרים מעל הנקודה הקודמת", r"E_E = 100 \cdot 10 \cdot 7 = 7000\,\text{J}"),
        S(r"אורך הקטע", r"הקטע ישר ומשופע. האורך הוא הגובה חלקי הסינוס של הזווית", r"DE = \frac{7}{\sin 53^\circ} \approx 8.77\,\text{m}"),
        S(r"העבודה של החיכוך", r"החיכוך נגד התנועה, והעבודה שלו שווה לשינוי באנרגיה המכנית", r"-f_k \cdot 8.77 = 7000 - 11000", eq=r"W_{\text{nc}} = \Delta E"),
        S(r"פותרים", r"מבודדים את כוח החיכוך", r"f_k = \frac{4000}{8.77} \approx 456.6\,\text{N}"),
    ], r"$\approx 456.6\,\text{N}$", key=r"f=456.6 N"),
  ],
  concepts=["שימור אנרגיה", "חוסר משקל בראש קשת", "כוח נורמלי במדרון", "עבודת חיכוך"],
  summary=r"מזחלת על מסלול שלג: המהירות, הגובה שבו מרגישים חסרי משקל, מה מראים המאזניים במדרון, וכוח החיכוך כשהשלג נמס.",
  review="הנחה שלי.\nבסעיף ד המאזניים מראים את הכוח הנורמלי על גיל בלבד, בלי המזחלת.\nמה לבדוק: רק לאשר.")
